using System;
using System.IO;
using System.Windows;
using System.Diagnostics;
using System.Windows.Media;
using System.Windows.Media.Imaging;

partial class Starship {
    static double Distance(FlightProfile.Pose a,FlightProfile.Pose b){return Math.Sqrt((a.X-b.X)*(a.X-b.X)+(a.Y-b.Y)*(a.Y-b.Y));}
    static void SelfTest(){
        string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"self-test");Directory.CreateDirectory(root);
        foreach(double width in new[]{700.0,1920})foreach(double height in new[]{900.0,1600}){
            double x=width*.67,bottom=height-110;
            for(double t=0;t<18;t+=.07){var f=FlightProfile.At(t,width,height,x,bottom);if(Math.Abs(Distance(f.Ship,f.Booster)-120)>.00001||Math.Abs(f.Ship.Angle-f.Booster.Angle)>.00001)throw new Exception("Attached stages separated early");}
            foreach(double t in new[]{7.0,18,24,30,36,49,56,57,64,77,84,90,96,101,108}){var a=FlightProfile.At(t-.000001,width,height,x,bottom);var b=FlightProfile.At(t+.000001,width,height,x,bottom);if(Distance(a.Booster,b.Booster)>.01||Math.Abs(a.Booster.Angle-b.Booster.Angle)>.01)throw new Exception("Booster trajectory discontinuity at "+t);if(a.Ship.Visible&&b.Ship.Visible&&(Distance(a.Ship,b.Ship)>.01||Math.Abs(a.Ship.Angle-b.Ship.Angle)>.01))throw new Exception("Ship trajectory discontinuity at "+t);}
            foreach(double stage in new[]{18.0,24,30,36,49,53}){var before=FlightProfile.At(stage-.02,width,height,x,bottom);var after=FlightProfile.At(stage+.02,width,height,x,bottom);if(Distance(before.Booster,after.Booster)/.04<.1)throw new Exception("Booster stopped at stage "+stage);}
            foreach(double stage in new[]{77.0,82,84,87,90,93}){var before=FlightProfile.At(stage-.02,width,height,x,bottom);var after=FlightProfile.At(stage+.02,width,height,x,bottom);if(Distance(before.Ship,after.Ship)/.04<.1)throw new Exception("Ship stopped at stage "+stage);}
            var boosterCatch=FlightProfile.At(56,width,height,x,bottom);if(Math.Abs(boosterCatch.ArmY-boosterCatch.Booster.Y-(72-68.5)*224/72)>.01)throw new Exception("Booster catch pin not aligned");var shipCatch=FlightProfile.At(96,width,height,x,bottom);if(Math.Abs(shipCatch.ArmY-shipCatch.Ship.Y+(40*224/72-120))>.01)throw new Exception("Ship catch pin not aligned");
            var reentry=FlightProfile.At(72,width,height,x,bottom);if(reentry.Ship.Heat<.5||Math.Abs(reentry.Ship.Angle)<70)throw new Exception("Reentry attitude or plasma missing");var done=FlightProfile.At(109,width,height,x,bottom);if(!done.Attached||Math.Abs(done.Booster.Y-(bottom-FlightProfile.HomeOffset))>.01||Math.Abs(done.Ship.Y-(bottom-FlightProfile.HomeOffset-120))>.01)throw new Exception("Restack missed");
        }
        var r=new Random(2345);int failures=0,crews=0;for(int i=0;i<100000;i++){if(MissionEffects.Choose(r)!=MissionScenario.Nominal)failures++;if(r.Next(5)==0)crews++;}if(failures<9500||failures>10500||crews<19000||crews>21000)throw new Exception("Outcome probabilities drifted");
        for(int i=0;i<75;i++){var p=MissionEffects.Debris(new Point(400,100),i,16,1092,700);if(p.X<0||p.X>700||p.Y>1092||p.Y<1030)throw new Exception("Debris did not settle within screen");}
        var stats=new MissionStats{Attempts=4,Takeoffs=3,Successes=2,Failures=2,CrewFlights=1,CrewBoarded=3,Tests=1};stats.Types[MissionScenario.PadExplosion]=1;stats.Save(Path.Combine(root,"stats.txt"));var copy=MissionStats.Load(Path.Combine(root,"stats.txt"));if(copy.Takeoffs!=3||copy.CrewBoarded!=3||copy.Types[MissionScenario.PadExplosion]!=1)throw new Exception("Stats roundtrip failed");
        var scene=new Starship{stats=new MissionStats(),statsPath=Path.Combine(root,"controller-stats.txt"),area=new Rect(0,0,700,1100),padX=450,padBottom=990};scene.BeginMission(MissionScenario.Nominal,true);scene.boarding=0;scene.elapsed=0;scene.StepMission(7.1);if(scene.stats.Takeoffs!=1)throw new Exception("Takeoff not counted");scene.StepMission(111);if(scene.stats.Successes!=1||scene.elapsed!=-1||scene.nextLaunch<120||scene.nextLaunch>360)throw new Exception("Mission completion failed");scene.randomLaunches=false;scene.nextLaunch=0;scene.StepMission(20);if(scene.elapsed!=-1)throw new Exception("Manual mode auto-launched");scene.BeginMission(MissionScenario.Nominal,true);scene.boarding=0;scene.elapsed=0;scene.paused=true;scene.StepMission(30);if(scene.elapsed!=0)throw new Exception("Pause failed");
        File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),"PASS: rigidly attached stages; continuous position/angle across flight boundaries at multiple screen sizes; reentry heat and attitude; final restack; 100,000 outcome samples (~10% failures, ~20% crew); falling debris bounds/settling; atomic persistent stats; takeoff and mission counts; random scheduling; manual mode; pause.\r\n");
    }
    static void RenderModelPreview(){var scene=new Starship{Width=700,Height=1100,elapsed=-1};var host=scene.PrepareModels();host.Width=700;host.Height=1100;host.Measure(new Size(700,1100));host.Arrange(new Rect(0,0,700,1100));scene.Snapshot("model-preview.png",700,1100);}
    static void RenderPreviews(){
        var scene=new Starship{Width=700,Height=1100};var host=scene.PrepareModels();host.Width=700;host.Height=1100;host.Measure(new Size(700,1100));host.Arrange(new Rect(0,0,700,1100));
        foreach(double t in new[]{-1.0,5,12,18,21,28,43,53,58,68,74,82,87,94,99,105,109}){scene.elapsed=t;scene.Snapshot("preview-"+t+".png",700,1100);}
        scene.elapsed=-1;scene.boarding=7;scene.Snapshot("preview-crew.png",700,1100);scene.boarding=0;
        foreach(MissionScenario scenario in Enum.GetValues(typeof(MissionScenario))){if(scenario==MissionScenario.Automatic||scenario==MissionScenario.Nominal)continue;scene.scenario=scenario;scene.elapsed=MissionEffects.IncidentTime(scenario)+.65;scene.Snapshot("preview-"+scenario+".png",700,1100);}scene.scenario=MissionScenario.Nominal;
        scene.Width=2160;scene.Height=3840;scene.Measure(new Size(2160,3840));scene.Arrange(new Rect(0,0,2160,3840));scene.elapsed=72;scene.Snapshot("preview-4k.png",2160,3840);
        scene.Width=700;scene.Height=1100;scene.Measure(new Size(700,1100));scene.Arrange(new Rect(0,0,700,1100));var clock=Stopwatch.StartNew();for(int i=0;i<120;i++){scene.elapsed=68+i/60.0;scene.InvalidateVisual();scene.UpdateLayout();}clock.Stop();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"render-check.txt"),"Rendered 24 flight/scenario/crew previews and a 2160×3840 frame. Cached vector vehicle artwork; active animation timer targets 60 Hz.\r\n120 reentry scene updates: "+clock.ElapsedMilliseconds+" ms (offscreen construction, not a live frame-rate measurement).\r\n");
    }
    void Snapshot(string name,int width,int height){if(sceneHost!=null){sceneHost.Width=width;sceneHost.Height=height;sceneHost.Measure(new Size(width,height));sceneHost.Arrange(new Rect(0,0,width,height));}InvalidateVisual();UpdateLayout();if(sceneHost!=null)sceneHost.UpdateLayout();var bmp=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);var layer=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);layer.Render(sceneHost==null?(System.Windows.Media.Visual)this:sceneHost);var visual=new DrawingVisual();using(var d=visual.RenderOpen()){d.DrawRectangle(B("#0D1624"),null,new Rect(0,0,width,height));d.DrawImage(layer,new Rect(0,0,width,height));}bmp.Render(visual);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var f=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name)))png.Save(f);}
}
